package computer.parachute.app

// Hand-written (not generated by `tauri android init`). Two things the shell's Rust side (src-tauri/src/key.rs and
// door.rs) needs from Android and can't do itself:
//  - keep the person's key: encrypted under a non-exportable AES-256-GCM key in the Android Keystore (alias
//    `parachute_key`); only the ciphertext and IV are written, to this app's private preferences. The plaintext never
//    touches disk and is never logged. (The Uni app keeps its key the same way.)
//  - put the hub's session cookie into the webview after a key sign-in (wry's set_cookie does nothing on Android).
// Only the shell's Rust side calls these: the plugin is registered from Rust and has no JavaScript-facing permission.

import android.app.Activity
import android.content.Context
import android.os.Build
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
import android.webkit.CookieManager
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

@InvokeArg
class SaveSecretArgs {
  lateinit var name: String
  lateinit var secret: String
}

@InvokeArg
class NameArgs {
  lateinit var name: String
}

@InvokeArg
class CookieArgs {
  lateinit var url: String
  lateinit var cookie: String
}

@TauriPlugin
class KeyPlugin(private val activity: Activity) : Plugin(activity) {
  companion object {
    /** This run of the app (a process): a missing Keystore key seen in an earlier run is believed (see loadSecret). */
    private val RUN: Long = System.nanoTime() xor System.currentTimeMillis() or 1L
  }

  private val keyAlias = "parachute_key"
  private val prefsName = "parachute_key"

  private fun prefs() = activity.getSharedPreferences(prefsName, Context.MODE_PRIVATE)

  private fun key(create: Boolean): SecretKey? {
    val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    (ks.getKey(keyAlias, null) as? SecretKey)?.let { return it }
    if (!create) return null
    val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
    gen.init(
      KeyGenParameterSpec.Builder(keyAlias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
        .setKeySize(256)
        .setRandomizedEncryptionRequired(true)
        .build()
    )
    return gen.generateKey()
  }

  @Command
  fun saveSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(SaveSecretArgs::class.java)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      cipher.init(Cipher.ENCRYPT_MODE, key(true))
      val ct = cipher.doFinal(args.secret.toByteArray(Charsets.UTF_8))
      val ok = prefs().edit()
        .putString("${args.name}.ct", Base64.encodeToString(ct, Base64.NO_WRAP))
        .putString("${args.name}.iv", Base64.encodeToString(cipher.iv, Base64.NO_WRAP))
        .remove("${args.name}.missing")
        .commit()
      if (!ok) {
        invoke.reject("could not write the encrypted key")
        return
      }
      invoke.resolve()
    } catch (e: Exception) {
      invoke.reject("keystore save failed: ${e.javaClass.simpleName}")
    }
  }

  @Command
  fun loadSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(NameArgs::class.java)
      val p = prefs()
      val ct = p.getString("${args.name}.ct", null)
      val iv = p.getString("${args.name}.iv", null)
      val out = JSObject()
      if (ct == null || iv == null) {
        out.put("secret", null as String?)
        invoke.resolve(out)
        return
      }
      val k = key(false)
      if (k == null) {
        // A key was kept but the Keystore key that opens it isn't there (a restore onto another phone). Through
        // Android 11 the Keystore answers "not there" when its service is restarting, too, so there a missing key is
        // believed only once an earlier run of the app also found it missing; until then it's a failure to retry.
        val missingIn = p.getLong("${args.name}.missing", 0L)
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S && (missingIn == 0L || missingIn == RUN)) {
          p.edit().putLong("${args.name}.missing", RUN).commit()
          invoke.reject("the key store didn't find its key; try again")
          return
        }
        out.put("secret", null as String?)
        out.put("unreadable", true)
        invoke.resolve(out)
        return
      }
      if (p.contains("${args.name}.missing")) p.edit().remove("${args.name}.missing").commit()
      val pt = try {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.DECRYPT_MODE, k, GCMParameterSpec(128, Base64.decode(iv, Base64.NO_WRAP)))
        cipher.doFinal(Base64.decode(ct, Base64.NO_WRAP))
      } catch (e: javax.crypto.BadPaddingException) {
        null // includes AEADBadTagException: the tag doesn't verify
      } catch (e: java.security.InvalidAlgorithmParameterException) {
        null // a damaged IV (wrong length)
      } catch (e: IllegalArgumentException) {
        null // not base64
      }
      if (pt == null) {
        // what is kept will never decrypt (its key was replaced, or it was damaged): only removing it helps
        out.put("secret", null as String?)
        out.put("unreadable", true)
        invoke.resolve(out)
        return
      }
      out.put("secret", String(pt, Charsets.UTF_8))
      pt.fill(0)
      invoke.resolve(out)
    } catch (e: Exception) {
      invoke.reject("keystore load failed: ${e.javaClass.simpleName}")
    }
  }

  @Command
  fun clearSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(NameArgs::class.java)
      prefs().edit().remove("${args.name}.ct").remove("${args.name}.iv").remove("${args.name}.missing").commit()
      val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
      if (ks.containsAlias(keyAlias)) ks.deleteEntry(keyAlias)
      invoke.resolve()
    } catch (e: Exception) {
      invoke.reject("keystore clear failed: ${e.javaClass.simpleName}")
    }
  }

  @Command
  fun setCookie(invoke: Invoke) {
    val args = invoke.parseArgs(CookieArgs::class.java)
    activity.runOnUiThread {
      try {
        val cookies = CookieManager.getInstance()
        cookies.setCookie(args.url, args.cookie) { ok ->
          cookies.flush()
          if (ok) invoke.resolve() else invoke.reject("the webview refused the cookie")
        }
      } catch (e: Exception) {
        invoke.reject("cookie failed: ${e.javaClass.simpleName}")
      }
    }
  }
}
